export interface InsuredItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: InsuredItem[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface StepResult {
  premium?: number;
  payout?: number;
  remainingCap?: number;
}

const PROCESSING_FEE = 5;
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
};
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PERCENT = 100;

function policyBasePremium(items: InsuredItem[]): number {
  return items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
}

// Amounts are kept in hundredths of a G so percentages stay exact until the final rounding.
function quote(step: QuoteStep): number {
  const premiumInHundredths = policyBasePremium(step.items) * (PERCENT + FIRST_INSURANCE_SURCHARGE_PERCENT);
  return Math.ceil(premiumInHundredths / PERCENT) + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  return { results: scenario.steps.map((step) => ({ premium: quote(step) })) };
}
import { describe, expect, it } from "vitest";
import { runScenario } from "./claim-office";

type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };

function premiumFor(items: Item[], yearsWithMHPCO = 0): number {
  const { results } = runScenario({ customer: { yearsWithMHPCO }, steps: [{ op: "quote", items }] });
  return results[0].premium as number;
}

describe("claim office quote", () => {
  it("empty item list -> premium 5 G (only the processing fee)", () => {
    expect(premiumFor([])).toBe(5);
  });
  it("plain sword for newcomer -> 100 base + 10 first insurance + 5 fee = 115 G", () => {
    expect(premiumFor([{ type: "sword" }])).toBe(115);
  });
  it("plain amulet for newcomer -> 60 base + 6 first insurance + 5 fee = 71 G", () => {
    expect(premiumFor([{ type: "amulet" }])).toBe(71);
  });
  it.todo("plain staff for newcomer -> 80 base + 8 first insurance + 5 fee = 93 G");
  it.todo("plain potion for newcomer -> 40 base + 4 first insurance + 5 fee = 49 G");
  it.todo("2 runes -> 50 G base premium -> 55 + 5 = 60 G");
  it.todo("1 moonstone -> 25 G base premium -> 27.5 + 5 = 32.5 -> 33 G (rounded up)");
  it.todo("3 runes -> 60 G base premium (block) -> 66 + 5 = 71 G");
  it.todo("4 runes -> 100 G base premium (no block) -> 110 + 5 = 115 G");
  it.todo("7 runes -> 175 G base premium -> 192.5 + 5 = 197.5 -> 198 G");
  it.todo("2 runes + 1 moonstone -> 75 G base premium (different types, no block) -> 82.5 + 5 -> 88 G");
  it.todo("3 runes + 3 moonstones -> 120 G base premium (two blocks) -> 132 + 5 = 137 G");
  it.todo("newcomer with a cursed sword (steel, enchantment 3) -> 165 G");
  it.todo("cursed sword + plain amulet -> 160 base + 50 curse on sword only + 16 first insurance + 5 fee = 231 G");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge -> 115 G");
  it.todo("sword with exactly enchantment 5 -> 30 % surcharge -> 100 + 30 + 10 + 5 = 145 G");
  it.todo("cursed sword with enchantment 5 -> both surcharges -> 100 + 50 + 30 + 10 + 5 = 195 G");
  it.todo("customer with exactly 2 years -> loyalty discount -> 100 - 20 + 10 + 5 = 95 G");
  it.todo("customer with 1 year -> no loyalty discount -> 115 G");
  it.todo("second quote in the scenario -> 15 % follow-up discount -> 100 + 10 - 15 + 5 = 100 G");
  it.todo("long-standing customer's second contract, cursed sword enchantment 7 -> 160 G");
  it.todo("cursed sword + 2 runes on second quote -> 197.5 G -> 198 G (rounded up in MHPCO's favor)");
